use super::*;
use crate::retirement::tests::{Wallet,physical_wallet,funded_turn,funded_close_owned};
fn turn(job:&mut AffineImageJob,wallet:&mut Wallet,items:usize)->Result<AffineImageProgress,AffineImageError>{funded_turn(wallet,items,|work,alloc|job.advance(items,work,alloc))}
fn semantic(job:&mut AffineImageJob,wallet:&mut Wallet,count:u64){let target=job.work+count;for _ in 0..2000000{if job.work>=target||job.phase=="complete"{return;}turn(job,wallet,1).unwrap();}panic!("finite observation bound exhausted");}
#[test]fn affine_retirement_preserves_real_private_owners_and_transfers_complete_pixels(){let sources:serde_json::Value=serde_json::from_str(crate::text("🎨️sampling/↗️affine/🧪️tests/🧫️fixtures/🔣️.json")).unwrap();let cases:serde_json::Value=serde_json::from_str(crate::text("🎨️sampling/↗️affine/🧪️tests/🧫️fixtures/🧹️retirement/🔣️.json")).unwrap();assert_eq!(cases.as_array().unwrap().len(),16);for row in cases.as_array().unwrap(){for quantum in [1,7,4096]{let source=sources.as_array().unwrap().iter().find(|v|v["name"]==row["source"]).unwrap();let mut v=input(&source["input"]);let mode=row["mode"].as_str().unwrap();if mode=="failure"{v.transform=[1e9,0.0,0.0,1.0,1e9,0.0];}let shared=Arc::clone(&v.source);let before=shared.pixels.clone();let mut job=AffineImageJob::new(v);let mut bank=physical_wallet();let phase=row["phase"].as_str().unwrap();if mode=="failure"{loop{if turn(&mut job,&mut bank,quantum).is_err(){break;}}assert!(job.failed.is_some());assert!(job.coverage.is_some());assert!(turn(&mut job,&mut bank,1).is_err());}else{let mut reached=false;for _ in 0..2000000{if job.phase==phase{reached=true;break;}turn(&mut job,&mut bank,1).unwrap();}assert!(reached,"{}",row["name"]);semantic(&mut job,&mut bank,row["steps"].as_u64().unwrap());}let candidate=job.output.pixels.as_ptr();let active=job.coverage.is_some();let closing=job.coverage_retirement.is_some();let published=if mode=="published"{Some(job.result().unwrap().pixels.clone())}else{None};if mode=="cancelled"||mode=="published"{job.cancel();assert_eq!(job.output.pixels.as_ptr(),candidate);assert_eq!(job.coverage.is_some(),active);assert_eq!(job.coverage_retirement.is_some(),closing);assert!(Arc::ptr_eq(&job.source.as_ref().unwrap().0,&shared));assert!(job.result().is_err());assert!(turn(&mut job,&mut bank,1).is_err());}let(retired,output)=job.into_retirement();assert_eq!(output.is_some(),phase=="complete"&&mode=="live");if let Some(image)=&output{assert_eq!(image.pixels.as_ptr(),candidate);let expected:Vec<u8>=serde_json::from_value(source["expected"].clone()).unwrap();assert_eq!(image.pixels,expected);}let state=retired.owner.original().unwrap();assert!(state.coverage.is_none());assert_eq!(state.coverage_retirement.is_some(),active||closing);assert!(Arc::ptr_eq(&state.source.as_ref().unwrap().0,&shared));if output.is_none(){assert_eq!(state.output.pixels.as_ptr(),candidate);}funded_close_owned((retired,output),&mut bank);assert_eq!(shared.pixels,before);assert_eq!(Arc::strong_count(&shared),1);if let Some(pixels)=published{let expected:Vec<u8>=serde_json::from_value(source["expected"].clone()).unwrap();assert_eq!(pixels,expected);}}}}
#[test]fn affine_sampling_retains_real_coverage_owners_until_publication_and_caller_close(){let sources:serde_json::Value=serde_json::from_str(crate::text("🎨️sampling/↗️affine/🧪️tests/🧫️fixtures/🔣️.json")).unwrap();let mut job=AffineImageJob::new(input(&sources[9]["input"]));let mut bank=physical_wallet();loop{turn(&mut job,&mut bank,1).unwrap();if job.phase=="coverageCleanup"{break;}}assert!(job.coverage.is_none());let mask=job.mask.as_ref().unwrap().coverage.as_ptr();assert!(!job.coverage_retirement.as_ref().unwrap().terminal_is_empty());turn(&mut job,&mut bank,1).unwrap();assert_eq!(job.phase,"sampling");assert_eq!(job.at,0);assert_eq!(job.mask.as_ref().unwrap().coverage.as_ptr(),mask);while !turn(&mut job,&mut bank,4096).unwrap().done{}let expected:Vec<u8>=serde_json::from_value(sources[9]["expected"].clone()).unwrap();assert_eq!(job.result().unwrap().pixels,expected);assert!(!job.coverage_retirement.as_ref().unwrap().terminal_is_empty());let(retired,output)=job.into_retirement();assert_eq!(output.as_ref().unwrap().pixels,expected);funded_close_owned((retired,output),&mut bank);}
#[test]fn affine_image_samples_match_every_shared_rgba_under_bounded_grants(){let cases:serde_json::Value=serde_json::from_str(crate::text("🎨️sampling/↗️affine/🧪️tests/🧫️fixtures/🔣️.json")).unwrap();for row in cases.as_array().unwrap(){for quantum in [1,7,4096]{let mut job=AffineImageJob::new(input(&row["input"]));let mut bank=physical_wallet();let mut previous=0;let mut done=false;for _ in 0..2000000{let p=turn(&mut job,&mut bank,quantum).unwrap();assert!(p.work-previous<=quantum as u64);previous=p.work;if p.done{done=true;break;}}assert!(done);let expected:Vec<u8>=serde_json::from_value(row["expected"].clone()).unwrap();assert_eq!(job.result().unwrap().pixels,expected,"{} quantum{quantum}",row["name"]);funded_close_owned(job.into_retirement(),&mut bank);}}}
#[test]fn affine_image_samples_refuse_partial_cancelled_and_failed_candidates(){let cases:serde_json::Value=serde_json::from_str(crate::text("🎨️sampling/↗️affine/🧪️tests/🧫️fixtures/🔣️.json")).unwrap();for steps in [0,1,5,20,60]{let mut job=AffineImageJob::new(input(&cases[9]["input"]));let mut bank=physical_wallet();assert!(job.result().is_err());semantic(&mut job,&mut bank,steps);job.cancel();assert!(turn(&mut job,&mut bank,1).is_err());assert!(job.result().is_err());funded_close_owned(job.into_retirement(),&mut bank);}for quantum in [0,usize::MAX]{let mut job=AffineImageJob::new(input(&cases[0]["input"]));let mut bank=physical_wallet();if quantum==0||usize::BITS>53{assert!(turn(&mut job,&mut bank,quantum).is_err());}funded_close_owned(job.into_retirement(),&mut bank);}let mut v=input(&cases[0]["input"]);v.width=0;let mut job=AffineImageJob::new(v);let mut bank=physical_wallet();assert!(turn(&mut job,&mut bank,1).is_err());funded_close_owned(job.into_retirement(),&mut bank);let mut v=input(&cases[9]["input"]);v.transform=[1e9,0.0,0.0,1.0,1e9,0.0];let mut job=AffineImageJob::new(v);let mut bank=physical_wallet();loop{if turn(&mut job,&mut bank,4096).is_err(){break;}}assert!(job.result().is_err());assert!(turn(&mut job,&mut bank,1).is_err());funded_close_owned(job.into_retirement(),&mut bank);}
fn input(v:&serde_json::Value)->AffineImageInput{let source=&v["source"];AffineImageInput{source:Arc::new(RasterImage{width:source["width"].as_u64().unwrap()as u32,height:source["height"].as_u64().unwrap()as u32,pixels:serde_json::from_value(source["pixels"].clone()).unwrap()}),width:v["width"].as_u64().unwrap()as u32,height:v["height"].as_u64().unwrap()as u32,origin:serde_json::from_value(v["origin"].clone()).unwrap(),transform:serde_json::from_value(v["transform"].clone()).unwrap(),sampling:match v["sampling"].as_str().unwrap(){"nearest"=>AffineSampling::Nearest,"bilinear"=>AffineSampling::Bilinear,"area"=>AffineSampling::Area,"auto"=>AffineSampling::Auto,_=>panic!("unknown fixture filter")}}}
#[test]fn affine_real_backing_admission_denial_and_independent_fixture_output(){let law:serde_json::Value=serde_json::from_str(include_str!("../🎟️work/📐️.json")).unwrap();assert_eq!(law["pixelBytes"],4);let cases:serde_json::Value=serde_json::from_str(crate::text("🎨️sampling/↗️affine/🧪️tests/🧫️fixtures/🔣️.json")).unwrap();let mut job=AffineImageJob::new(input(&cases[9]["input"]));let mut bank=crate::retirement::tests::physical_wallet();let mut denied=[false;4];loop{let mut d=job.next_work_demand();if !denied[2]&&d.capacity_bytes==0{let before=job.work;let mut grant=bank.remaining();grant.maximum_capacity_bytes=0;let((p,receipt),heap)=crate::retirement::tests::observed(||{let mut work=semio_framework_value::work::RetainedWorkLedger::new(grant);let p=job.advance(1,&mut work,&mut None).unwrap();(p,work.receipt())});if receipt==Default::default(){assert!(!p.done);assert_eq!(heap,(0,0));assert_eq!(job.work,before);assert_eq!(job.last_turn_work(),0);}}d=job.next_work_demand();for axis in 0..4{let n=match axis{0=>1,1=>d.copy_bytes,2=>d.capacity_bytes,_=>d.depth};if n==0||denied[axis]{continue;}let mut grant=bank.remaining();*match axis{0=>&mut grant.maximum_items,1=>&mut grant.maximum_copy_bytes,2=>&mut grant.maximum_capacity_bytes,_=>&mut grant.maximum_depth}=n-1;let before=job.work;let((p,receipt),heap)=crate::retirement::tests::observed(||{let mut work=semio_framework_value::work::RetainedWorkLedger::new(grant);let p=job.advance(1,&mut work,&mut None).unwrap();(p,work.receipt())});assert!(!p.done);assert_eq!(heap,(0,0));assert_eq!(receipt,Default::default());assert_eq!(job.work,before);assert_eq!(job.last_turn_work(),0);denied[axis]=true;}if crate::retirement::tests::funded_turn(&mut bank,1,|work,alloc|job.advance(1,work,alloc)).unwrap().done{break;}}assert!(denied.into_iter().all(|v|v));let expected:Vec<u8>=serde_json::from_value(cases[9]["expected"].clone()).unwrap();assert_eq!(job.result().unwrap().pixels,expected);crate::retirement::tests::funded_close_owned(job.into_retirement(),&mut bank);}
